const $=(s,r=document)=>r.querySelector(s);const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"></use></svg>`;
const zh={queue:'任务队列',members:'成员',agents:'Agents',settings:'项目设置',users:'用户管理',projects:'项目管理',activity:'活动记录',globalSettings:'系统设置',account:'我的账号',createItem:'新建工单',createProject:'新建项目',createUser:'创建用户',createAgent:'创建 Agent',search:'搜索标题或编号…',all:'全部',mine:'我的任务',logout:'退出登录',empty:'这里还没有工单',emptyNote:'创建第一张工单，让讨论、执行与验收沿同一条可审计路线推进。',todo:'待办',discussion:'讨论',execution:'执行',acceptance:'验收',completed:'完成',abandoned:'已放弃',blocked:'已阻塞',workspace:'工作区',system:'系统',profile:'个人',save:'保存',cancel:'取消',submit:'提交',close:'关闭',noProjects:'还没有项目',noProjectsNote:'创建项目后即可配置仓库授权、成员和 Agent。'};
const en={queue:'Task queue',members:'Members',agents:'Agents',settings:'Project settings',users:'User management',projects:'Project management',activity:'Activity',globalSettings:'System settings',account:'My account',createItem:'New work item',createProject:'New project',createUser:'Create user',createAgent:'Create Agent',search:'Search title or ID…',all:'All',mine:'My work',logout:'Sign out',empty:'No work items yet',emptyNote:'Create the first item to move discussion, execution, and acceptance through one auditable route.',todo:'Todo',discussion:'Discussion',execution:'Execution',acceptance:'Acceptance',completed:'Completed',abandoned:'Abandoned',blocked:'Blocked',workspace:'Workspace',system:'System',profile:'Personal',save:'Save',cancel:'Cancel',submit:'Submit',close:'Close',noProjects:'No projects yet',noProjectsNote:'Create a project, then configure repository access, members, and Agents.'};
const state={me:null,projects:[],project:null,page:'queue',items:[],locale:localStorage.pbLocale||'zh',task:null,drawer:null,lastFocus:null};const t=k=>(state.locale==='zh'?zh:en)[k]||k;
async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(!['GET','HEAD'].includes(options.method||'GET')){const csrf=document.cookie.split('; ').find(x=>x.startsWith('pb_csrf='))?.split('=')[1];if(csrf)headers['X-CSRF-Token']=decodeURIComponent(csrf)}const response=await fetch(path,{...options,headers});let value=null;const type=response.headers.get('content-type')||'';if(type.includes('json'))value=await response.json();if(!response.ok)throw new Error(value?.error?.message||response.statusText);return value}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function escapeHTML(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function field(label,name,type='text',value='',extra=''){return `<label class="field"><span>${escapeHTML(label)}</span><input name="${name}" type="${type}" value="${escapeHTML(value)}" ${extra}></label>`}
function area(label,name,value='',extra=''){return `<label class="field"><span>${escapeHTML(label)}</span><textarea name="${name}" ${extra}>${escapeHTML(value)}</textarea></label>`}
function badge(text,kind=''){return `<span class="badge ${kind}">${escapeHTML(text)}</span>`}
function header(title,description,actions='',tools=''){return `<header class="page-head"><div class="page-title"><div><h1>${escapeHTML(title)}</h1><p>${escapeHTML(description)}</p></div><div class="page-actions">${actions}</div></div>${tools?`<div class="tools">${tools}</div>`:''}</header>`}
async function boot(){try{state.me=await api('/api/me');await loadProjects();renderShell()}catch{renderLogin()}}
function renderLogin(){$('#app').innerHTML=`<main class="login-screen"><section class="login-panel"><div class="brand"><span class="brand-mark">PB</span><span>ProjectBoard / Secure queue</span></div><div class="login-copy"><h1>Work moves<br>with proof.</h1><p>Human and Agent work follows one visible route. Every conclusion, execution and acceptance stays attached to the item.</p></div><form class="login-form" id="loginForm">${field('Username','username','text','admin','required autocomplete="username"')}${field('Password','password','password','','required autocomplete="current-password"')}<div class="form-error" hidden></div><button class="button primary" type="submit">Sign in ${icon('chevron')}</button></form></section><aside class="login-art"><div class="route-diagram"><span>DISCUSS</span><i></i><span>EXECUTE</span><i></i><span>ACCEPT</span></div></aside></main>`;$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=$('button',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{const result=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});state.me=result.user;await loadProjects();renderShell()}catch(x){error.textContent=x.message;error.hidden=false}finally{button.disabled=false}})}
async function loadProjects(){state.projects=await api('/api/projects');const saved=localStorage.pbProject;state.project=state.projects.find(p=>p.id===saved)||state.projects[0]||null;if(state.project)localStorage.pbProject=state.project.id}
const nav1=[['queue','list'],['members','users'],['agents','bot'],['settings','settings']],nav2=[['users','users'],['projects','grid'],['activity','activity'],['globalSettings','settings']],navButton=([page,i])=>`<button data-page="${page}" class="${state.page===page?'active':''}">${icon(i)}<span>${t(page)}</span></button>`;
function renderShell(){$('#app').innerHTML=`<div class="shell"><header class="mast"><div class="brand"><span class="brand-mark">PB</span><span>ProjectBoard</span></div><div class="mast-actions"><button class="button" id="locale">${state.locale==='zh'?'EN':'中文'}</button><button class="icon-button" data-page="account" aria-label="${t('account')}">${icon('user')}</button></div></header><div class="workspace-grid"><aside class="rail"><button class="project-switch" id="projectSwitch"><span class="project-mark">${state.project?escapeHTML(state.project.key.slice(0,2).toUpperCase()):'--'}</span><span><strong>${escapeHTML(state.project?.name||t('noProjects'))}</strong><small>${escapeHTML(state.project?.repositoryUrl||'PROJECT SETUP')}</small></span>${icon('chevron')}</button><span class="rail-label">${t('workspace')}</span><nav class="nav">${nav1.map(navButton).join('')}</nav><span class="rail-label">${t('system')}</span><nav class="nav">${nav2.map(navButton).join('')}</nav><span class="rail-label">${t('profile')}</span><nav class="nav"><button data-page="account" class="${state.page==='account'?'active':''}">${icon('user')}<span>${t('account')}</span></button></nav><div class="rail-foot">GO SERVER / SQLITE WAL<br>STATIC WORKSPACE EMBEDDED</div></aside><main class="workspace" id="workspace"></main></div></div><div class="drawer-backdrop" id="drawerBackdrop"></div><aside class="drawer" id="drawer" role="dialog" aria-modal="true" aria-hidden="true"></aside>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#locale').onclick=()=>{state.locale=state.locale==='zh'?'en':'zh';localStorage.pbLocale=state.locale;renderShell()};$('#projectSwitch').onclick=projectPicker;$('#drawerBackdrop').onclick=closeDrawer;document.addEventListener('keydown',escapeDrawer,{once:true});renderPage()}
function escapeDrawer(e){if(e.key==='Escape')closeDrawer();else document.addEventListener('keydown',escapeDrawer,{once:true})}
function navigate(page){state.page=page;state.task=null;renderShell()}
async function renderPage(){const root=$('#workspace');root.innerHTML='<div class="loading">CALIBRATING WORKSPACE…</div>';try{if(state.page==='queue')await renderQueue();else if(state.page==='members')await renderMembers();else if(state.page==='agents')await renderAgents();else if(state.page==='settings')await renderSettings();else if(state.page==='users')await renderUsers();else if(state.page==='projects')await renderProjects();else if(state.page==='activity')await renderActivity();else if(state.page==='globalSettings')await renderSystemSettings();else await renderAccount()}catch(e){root.innerHTML=header('Unable to load','The workspace returned an error.')+`<div class="content"><div class="form-error">${escapeHTML(e.message)}</div></div>`}}
async function renderQueue(){if(!state.project){$('#workspace').innerHTML=header(t('queue'),t('noProjectsNote'),`<button class="button primary" id="createProject">${icon('plus')}${t('createProject')}</button>`)+emptyState(t('noProjects'),t('noProjectsNote'));$('#createProject').onclick=projectForm;return}state.items=await api(`/api/work-items?projectId=${encodeURIComponent(state.project.id)}`);if(state.task){await renderTask();return}const actions=`<button class="button primary" id="newItem">${icon('plus')}${t('createItem')}</button>`;const tools=`<label class="search">${icon('search')}<input id="queueSearch" placeholder="${t('search')}"></label>${badge(`${state.items.length} ITEMS`)}`;const rows=state.items.map(item=>`<button class="work-row" data-id="${item.id}"><i class="priority-bar ${item.priority}"></i><span class="work-title"><strong>${escapeHTML(item.title)}</strong><small>${item.id} / ${escapeHTML(item.target_branch)} / V${item.version}</small></span><span class="row-meta">${item.blocked_at?badge(t('blocked'),'danger'):''}${badge(t(item.stage),item.stage==='execution'||item.stage==='acceptance'?'signal':'')}</span></button>`).join('');$('#workspace').innerHTML=header(t('queue'),`${state.project.name} / ${state.project.repositoryUrl}`,actions,tools)+`<div class="content">${rows?`<section class="queue-group"><div class="group-label">CURRENT ROUTE / ${state.items.length}</div>${rows}</section>`:emptyState(t('empty'),t('emptyNote'))}</div>`;$('#newItem').onclick=workItemForm;document.querySelectorAll('.work-row').forEach(row=>row.onclick=()=>{state.task=row.dataset.id;renderQueue()});$('#queueSearch').oninput=e=>document.querySelectorAll('.work-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}
function emptyState(title,note){return `<section class="empty"><div class="empty-inner"><div class="empty-index">00</div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(note)}</p></div></section>`}
const stages=['todo','discussion','execution','acceptance','completed'];
async function renderTask(){const item=await api(`/api/work-items/${state.task}`);const index=stages.indexOf(item.stage);const track=stages.map((s,i)=>`<div class="stage ${i<index?'done':i===index?'current':''}">${t(s)}</div>`).join('');const events=(item.conversation||[]).map(e=>{const p=e.payload||JSON.parse(e.payload_json||'{}');return `<article class="event"><div class="event-meta">${escapeHTML(e.kind)}<br>${escapeHTML(e.created_at||'')}</div><div class="event-body">${escapeHTML(p.markdown||p.noteMarkdown||p.reason||JSON.stringify(p,null,2))}</div></article>`}).join('');$('#workspace').innerHTML=`<header class="page-head task-head"><button class="back" id="back">${icon('chevron')} ${t('queue')}</button><div class="page-title"><div><h1>${escapeHTML(item.title)}</h1><p>${item.id} / VERSION ${item.version} / ${escapeHTML(item.target_branch)}</p></div><div class="page-actions"><button class="button" id="message">Add message</button><button class="button" id="stageAction">Stage action</button></div></div><div class="stage-wrap"><div class="stage-track">${track}</div></div></header><div class="content task-body"><div class="task-summary"><section class="prose"><h2>Work item</h2><p>${escapeHTML(item.description_markdown||'No description.')}</p><h2>Acceptance criteria</h2><p>${escapeHTML(item.acceptance_criteria_markdown||'No criteria.')}</p></section><aside class="settings-section"><div class="kv"><div><dt>Stage</dt><dd>${escapeHTML(item.stage)}</dd></div><div><dt>Priority</dt><dd>${escapeHTML(item.priority)}</dd></div><div><dt>Assignee</dt><dd>${escapeHTML(item.assignee_kind||'unassigned')}</dd></div><div><dt>Blocked</dt><dd>${item.blocked_at?'YES':'NO'}</dd></div></div></aside></div><section class="conversation"><h2>Continuous conversation</h2>${events||'<p>No events.</p>'}</section></div>`;$('#back').onclick=()=>{state.task=null;renderQueue()};$('#message').onclick=()=>messageForm(item);$('#stageAction').onclick=()=>stageForm(item)}
function openDrawer(title,body,onReady){state.lastFocus=document.activeElement;const drawer=$('#drawer'),back=$('#drawerBackdrop');drawer.innerHTML=`<header class="drawer-head"><h2>${escapeHTML(title)}</h2><button class="icon-button" id="closeDrawer" aria-label="${t('close')}">${icon('x')}</button></header>${body}`;drawer.classList.add('open');back.classList.add('open');drawer.setAttribute('aria-hidden','false');$('#closeDrawer').onclick=closeDrawer;onReady?.(drawer);setTimeout(()=>drawer.querySelector('input,button,select,textarea')?.focus(),20)}
function closeDrawer(){clearInterval(state.gitPoll);state.gitPoll=null;const drawer=$('#drawer');if(!drawer)return;drawer.classList.remove('open');$('#drawerBackdrop')?.classList.remove('open');drawer.setAttribute('aria-hidden','true');state.lastFocus?.focus()}
function wireForm(selector,submit){const form=$(selector);form.onsubmit=async e=>{e.preventDefault();const button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await submit(Object.fromEntries(new FormData(form)));closeDrawer();await loadProjects();await renderPage()}catch(x){error.textContent=x.message;error.hidden=false}finally{button.disabled=false}}}
function formShell(fields,note=''){return `${note?`<p class="drawer-note">${escapeHTML(note)}</p>`:''}<form class="form" id="drawerForm">${fields}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`}
async function workItemForm(){const [members,agents]=await Promise.all([api(`/api/projects/${state.project.id}/members`),api(`/api/projects/${state.project.id}/agents`)]);const choices=[...members.filter(x=>x.role&&x.status==='active').map(x=>`<option value="human:${x.id}">${escapeHTML(x.displayName)} / human</option>`),...agents.filter(x=>x.enabled&&x.status==='active').map(x=>`<option value="agent:${x.id}">${escapeHTML(x.name)} / Agent</option>`)].join('');const fields=field('Title','title','text','','required')+area('Description','descriptionMarkdown')+area('Acceptance criteria','acceptanceCriteriaMarkdown','','required')+`<label class="field"><span>Priority</span><select name="priority"><option>medium</option><option>urgent</option><option>high</option><option>low</option></select></label><label class="field"><span>Assignee</span><select name="assignee" required><option value="">Select an executor</option>${choices}</select></label>`;openDrawer(t('createItem'),formShell(fields,'Assigning an executor starts the discussion stage immediately.'),()=>wireForm('#drawerForm',d=>{const [assigneeKind,assigneeId]=d.assignee.split(':');delete d.assignee;return api('/api/work-items',{method:'POST',body:JSON.stringify({...d,assigneeKind,assigneeId,projectId:state.project.id,requestId:crypto.randomUUID()})})}))}
function messageForm(item){openDrawer('Continue conversation',formShell(area('Message','markdown','','required')),()=>wireForm('#drawerForm',d=>api(`/api/work-items/${item.id}/messages`,{method:'POST',body:JSON.stringify({...d,requestId:crypto.randomUUID(),expectedVersion:item.version})})))}
function stageForm(item){let fields='';let path='';if(item.blocked_at){path='unblock';fields='<p class="drawer-note">Clear the additive blocked marker. The stage will not change.</p>'}else if(item.stage==='discussion'){path='discussion-conclusions';fields=area('Goal','goalMarkdown','','required')+area('Scope','scopeMarkdown','','required')+area('Out of scope','outOfScopeMarkdown')+area('Implementation plan','implementationPlanMarkdown','','required')+area('Acceptance criteria','acceptanceCriteriaMarkdown','','required')+area('Risks','risksMarkdown')}else if(item.stage==='execution'){path='submit-execution';fields=area('Summary','summaryMarkdown','','required')+field('Commit SHA','commit')+area('Changed files','files')+`<input type="hidden" name="pushed" value="true"><input type="hidden" name="worktreeClean" value="true"><input type="hidden" name="forbiddenPathsClean" value="true">`}else if(item.stage==='acceptance'){path='acceptance-attempts';fields=`<label class="field"><span>Outcome</span><select name="outcome"><option value="pass">Pass</option><option value="changes_requested">Changes requested</option><option value="scope_unclear">Scope unclear</option><option value="abandon">Abandon</option></select></label>`+area('Note','noteMarkdown','','required')}else{path='block';fields=area('Block reason','reason','','required')}openDrawer('Stage action',formShell(fields),()=>wireForm('#drawerForm',d=>{const body={...d,requestId:crypto.randomUUID(),expectedVersion:item.version};if(path==='submit-execution'){body.commits=d.commit?[d.commit]:[];body.changedFiles=d.files?d.files.split(/\r?\n/).filter(Boolean):[];body.validations=[];body.remainingRisksMarkdown='';delete body.commit;delete body.files;body.pushed=true;body.worktreeClean=true;body.forbiddenPathsClean=true}return api(`/api/work-items/${item.id}/${path}`,{method:'POST',body:JSON.stringify(body)})}))}
function projectForm(){openDrawer(t('createProject'),formShell(field('Name','name','text','','required')+field('Project key','key','text','','required pattern="[A-Za-z][A-Za-z0-9-]{1,19}"')+field('Repository URL','repositoryUrl','url','','required')),()=>wireForm('#drawerForm',d=>api('/api/projects',{method:'POST',body:JSON.stringify(d)})))}
function projectPicker(){const options=state.projects.map(p=>`<button class="work-row" data-project="${p.id}"><i class="priority-bar"></i><span class="work-title"><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.repositoryUrl)}</small></span>${p.id===state.project?.id?badge('CURRENT','signal'):''}</button>`).join('');openDrawer('Switch project',`<div class="table">${options||emptyState(t('noProjects'),t('noProjectsNote'))}</div><p><button class="button primary" id="newProjectInPicker">${icon('plus')}${t('createProject')}</button></p>`,drawer=>{drawer.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{state.project=state.projects.find(p=>p.id===b.dataset.project);localStorage.pbProject=state.project.id;closeDrawer();renderShell()});$('#newProjectInPicker').onclick=projectForm})}
async function renderMembers(){if(!state.project)return renderQueue();const data=await api(`/api/projects/${state.project.id}/members`);const rows=data.map(x=>`<button class="table-row action management-row" data-member="${x.id}"><span><strong>${escapeHTML(x.displayName)}</strong><small>@${escapeHTML(x.username)}</small></span><span>${escapeHTML(x.status)}</span><span>${escapeHTML(x.systemRole)}</span><span class="row-end">${x.role?badge(x.role,'signal'):badge('not a member')}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('members'),'Human accounts and project roles. Select an account to configure its access.')+`<div class="content"><div class="table">${rows}</div></div>`;document.querySelectorAll('[data-member]').forEach(row=>row.onclick=()=>memberSettings(data.find(x=>x.id===row.dataset.member)))}
function memberSettings(member){const hasAccess=Boolean(member.role);const roleField=`<label class="field"><span>Project role</span><select name="role"><option value="developer" ${member.role==='developer'?'selected':''}>Developer</option><option value="viewer" ${member.role==='viewer'?'selected':''}>Viewer</option></select></label>`;openDrawer('Member settings',`<section class="entity-summary"><span class="user-avatar large">${escapeHTML(member.displayName.trim().slice(0,1).toUpperCase()||'?')}</span><div><span class="eyebrow">HUMAN ACCOUNT / @${escapeHTML(member.username)}</span><h3>${escapeHTML(member.displayName)}</h3><div>${badge(member.status,member.status==='disabled'?'danger':'')} ${badge(member.systemRole)}</div></div></section>${formShell(roleField,hasAccess?'Changing this role only affects the current project.':'Add this organization account to the current project.')} ${hasAccess?'<section class="drawer-section"><button class="button danger" id="removeMember" type="button">Remove from project</button></section>':''}`,()=>{wireForm('#drawerForm',d=>api(`/api/projects/${state.project.id}/members${hasAccess?`/${member.id}`:''}`,{method:hasAccess?'PATCH':'POST',body:JSON.stringify(hasAccess?d:{userId:member.id,...d})}));const remove=$('#removeMember');if(remove)remove.onclick=async()=>{remove.disabled=true;try{await api(`/api/projects/${state.project.id}/members/${member.id}`,{method:'DELETE',body:'{}'});closeDrawer();toast('Member removed');renderMembers()}catch(error){toast(error.message);remove.disabled=false}}})}
async function renderAgents(){if(!state.project)return renderQueue();const data=await api(`/api/projects/${state.project.id}/agents`);const actions=`<button class="button primary" id="newAgent">${icon('plus')}${t('createAgent')}</button>`;const rows=data.map(x=>`<button class="table-row action management-row" data-agent="${x.id}"><span><strong>${escapeHTML(x.name)}</strong><small>${escapeHTML(x.purpose)}</small></span><span>${escapeHTML(x.status)}</span><span>Runner identity</span><span class="row-end">${badge(x.enabled?'enabled':'disabled',x.enabled?'signal':'')}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('agents'),'Organization identities; select an Agent to manage project access.',actions)+`<div class="content"><div class="table">${rows}</div></div>`;$('#newAgent').onclick=agentForm;document.querySelectorAll('[data-agent]').forEach(row=>row.onclick=()=>agentSettings(data.find(x=>x.id===row.dataset.agent)))}
function agentSettings(agent){openDrawer('Agent settings',`<section class="entity-summary"><span class="entity-mark">${icon('bot')}</span><div><span class="eyebrow">AGENT IDENTITY</span><h3>${escapeHTML(agent.name)}</h3><div>${badge(agent.status)} ${badge(agent.enabled?'enabled in project':'not enabled',agent.enabled?'signal':'')}</div></div></section><section class="drawer-section"><span class="eyebrow">PURPOSE</span><p class="detail-copy">${escapeHTML(agent.purpose||'No purpose provided.')}</p></section><section class="drawer-section"><span class="eyebrow">PROJECT ACCESS</span><p class="detail-copy">${agent.enabled?'This Agent can be assigned work in the current project.':'Enable this Agent before assigning project work.'}</p><button class="button ${agent.enabled?'danger':'primary'}" id="toggleAgent" type="button">${agent.enabled?'Disable for project':'Enable for project'}</button></section>`,()=>{$('#toggleAgent').onclick=async()=>{const button=$('#toggleAgent');button.disabled=true;try{await api(`/api/projects/${state.project.id}/agents/${agent.id}`,{method:agent.enabled?'DELETE':'PUT',body:'{}'});closeDrawer();toast(agent.enabled?'Agent disabled for project':'Agent enabled for project');renderAgents()}catch(error){toast(error.message);button.disabled=false}}})}
function agentForm(){openDrawer(t('createAgent'),formShell(field('Name','name','text','','required')+area('Purpose','purpose','','required')),()=>wireForm('#drawerForm',async d=>{const agent=await api('/api/agents',{method:'POST',body:JSON.stringify(d)});const pairing=await api(`/api/agents/${agent.id}/pairing-codes`,{method:'POST',body:'{}'});toast(`Pairing code: ${pairing.code}`)}))}
async function renderSystemSettings(){const settings=await api('/api/system/settings');const value=settings.publicUrl||location.origin;$('#workspace').innerHTML=header(t('globalSettings'),'One address for provider callbacks across every project.')+`<div class="content system-settings"><section class="settings-section"><h2>ProjectBoard address</h2><p>Used only when GitHub or GitLab redirects your browser back to ProjectBoard. Localhost is supported.</p><form class="form" id="systemSettingsForm">${field('ProjectBoard URL','publicUrl','url',value,'required')}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form></section><section class="settings-section"><h2>Git synchronization</h2><div class="kv"><div><dt>Mode</dt><dd>ON DEMAND</dd></div><div><dt>Webhook</dt><dd>DISABLED</dd></div></div><p>ProjectBoard queries recent commits only when a person clicks Sync recent commits or an active Runner notifies the project.</p></section></div>`;$('#systemSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api('/api/system/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast('System settings saved');renderSystemSettings()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}}
async function renderSettings(){if(!state.project)return renderQueue();let grant=null;try{grant=await api(`/api/projects/${state.project.id}/repository-grant`)}catch{}const actions=`<button class="button" id="editProject">Edit settings</button>${grant?`<button class="button" id="syncCommits">${icon('activity')}Sync recent commits</button>`:''}<button class="button primary" id="gitGrant">${icon('git')}${grant?'Change Git access':'Automatic Git setup'}</button>`;$('#workspace').innerHTML=header(t('settings'),'Repository rules and independently approved access.',actions)+`<div class="content settings-grid"><section class="settings-section"><h2>Repository authorization</h2>${grant?`<div class="kv"><div><dt>Provider</dt><dd>${escapeHTML(grant.provider)}</dd></div><div><dt>Authorization</dt><dd>${escapeHTML(grant.authorizationName)}</dd></div><div><dt>Repository</dt><dd>${escapeHTML(grant.repositoryName)}</dd></div><div><dt>Access</dt><dd>${escapeHTML(grant.accessLevel)}</dd></div><div><dt>Commit sync</dt><dd>ON DEMAND</dd></div></div>`:'<p>No repository grant. Use Automatic Git setup to connect a provider, list its repositories, then confirm this project’s exact access.</p>'}</section><section class="settings-section"><h2>Repository & branches</h2><div class="kv"><div><dt>Repository URL</dt><dd>${escapeHTML(state.project.repositoryUrl)}</dd></div><div><dt>Default target</dt><dd>${escapeHTML(state.project.defaultTargetBranch)}</dd></div><div><dt>Allowed</dt><dd>${escapeHTML((state.project.allowedTargetBranches||[]).join(', '))}</dd></div><div><dt>Config version</dt><dd>${state.project.configVersion}</dd></div></div></section><section class="settings-section"><h2>Execution policy</h2><p>Runner pushes only controlled task branches. After a push, an active Runner can notify ProjectBoard to query recent commits.</p></section><section class="settings-section"><h2>Credential policy</h2><p>No Webhook listener or background polling is used. Provider secrets remain encrypted, and every manual or Runner-triggered sync is project-scoped and audited.</p></section></div>`;$('#editProject').onclick=()=>editProjectForm(state.project);$('#gitGrant').onclick=grantForm;const sync=$('#syncCommits');if(sync)sync.onclick=async()=>{sync.disabled=true;try{const result=await api(`/api/projects/${state.project.id}/sync-commits`,{method:'POST',body:'{}'});toast(`Fetched ${result.fetched}; attached ${result.inserted} commit${result.inserted===1?'':'s'}`)}catch(error){toast(error.message)}finally{sync.disabled=false}}}
function editProjectForm(p){openDrawer('Edit project',formShell(field('Name','name','text',p.name,'required')+field('Repository URL','repositoryUrl','url',p.repositoryUrl)+field('Default target branch','defaultTargetBranch','text',p.defaultTargetBranch)+area('Allowed branches','allowed',p.allowedTargetBranches.join('\n'))),()=>wireForm('#drawerForm',d=>api(`/api/projects/${p.id}`,{method:'PATCH',body:JSON.stringify({...d,allowedTargetBranches:d.allowed.split(/\s+/).filter(Boolean)})})))}
async function grantForm(){const [configuration,settings,auths]=await Promise.all([api('/api/git/connections'),api('/api/git/provider-settings'),api('/api/provider-authorizations')]);const providerButton=(provider,label)=>{const configured=configuration[provider]?.configured;const setupLabel=provider==='github'?'Set up GitHub automatically':'Configure GitLab';const setupCopy=provider==='github'?'GitHub creates the App and key; ProjectBoard fills everything in.':'Add the OAuth application settings securely in ProjectBoard.';return `<button class="connection-provider" type="button" ${configured?`data-connect-provider="${provider}"`:`data-config-provider="${provider}"`}><span class="entity-mark">${icon(configured?'git':'settings')}</span><span><strong>${configured?label:setupLabel}</strong><small>${configured?'Continue on the provider’s official authorization page.':setupCopy}</small></span>${configured?badge('ready','signal'):badge('setup required')}${icon('chevron')}</button>`};const reusable=auths.filter(a=>a.status==='active'&&a.webhookStatus==='on_demand').map(a=>`<button class="connection-provider compact" type="button" data-reuse-authorization="${a.id}"><span><strong>${escapeHTML(a.name)}</strong><small>${escapeHTML(a.provider)} · ${a.bindingCount} project grants · on-demand sync</small></span>${icon('chevron')}</button>`).join('');const configuredCount=['github','gitlab'].filter(provider=>settings[provider]?.configured).length;openDrawer('Automatic Git setup',`<p class="drawer-note">Choose a provider, confirm its repositories, then approve the exact project access. Recent commits are queried only when a person or active Runner requests a sync.</p><div class="configuration-meter"><strong>${configuredCount} / 2 providers ready</strong><span>No Webhook listener or background polling is enabled.</span></div><section class="connection-section"><span class="eyebrow">PROVIDER CONNECTIONS</span><div class="connection-options">${providerButton('github','Connect GitHub')}${providerButton('gitlab','Connect GitLab')}</div></section>${reusable?`<section class="drawer-section"><span class="eyebrow">REUSE A VERIFIED CONNECTION</span><div class="connection-options">${reusable}</div></section>`:''}<section class="drawer-section"><button class="text-action" id="manualGitLab" type="button">Advanced: configure a GitLab access token manually</button><p class="inline-note">Only administrators can change provider application settings. Saved secret values are write-only.</p></section>`,drawer=>{drawer.querySelectorAll('[data-connect-provider]').forEach(button=>button.onclick=()=>startGitConnection(button.dataset.connectProvider));drawer.querySelectorAll('[data-config-provider]').forEach(button=>button.onclick=()=>providerSettingsForm(button.dataset.configProvider,settings[button.dataset.configProvider]));drawer.querySelectorAll('[data-reuse-authorization]').forEach(button=>button.onclick=()=>reuseAuthorization(button.dataset.reuseAuthorization,auths.find(a=>a.id===button.dataset.reuseAuthorization)));$('#manualGitLab').onclick=providerAuthorizationForm})}
function providerSettingsForm(provider,current={}){if(provider==='github')return githubQuickSetup(current);return manualProviderSettingsForm(provider,current)}
async function githubQuickSetup(current={}){const system=await api('/api/system/settings');const returnAddress=system.publicUrl||location.origin;const repositoryOwner=(()=>{try{const parsed=new URL(state.project?.repositoryUrl||'');return parsed.hostname==='github.com'?parsed.pathname.split('/').filter(Boolean)[0]||'':''}catch{return''}})();openDrawer('Connect GitHub',`<section class="manifest-intro"><span class="manifest-mark">${icon('git')}</span><div><h3>One confirmation on GitHub</h3><p>ProjectBoard creates the App configuration automatically and saves the generated key encrypted. No Webhook is created.</p></div></section><form class="form manifest-form" id="githubManifestForm"><input type="hidden" name="detectedPublicUrl" value="${escapeHTML(returnAddress)}"><div class="provider-callbacks"><strong>Return address</strong><code>${escapeHTML(returnAddress)}</code></div><details class="manifest-advanced"><summary>Create the App under a GitHub organization</summary>${field('Organization account slug','organization','text','','placeholder="'+escapeHTML(repositoryOwner||'my-organization')+'"')}<p>Leave blank to create it under your personal GitHub account.</p></details><div class="permission-summary manifest-permissions"><strong>Settings GitHub will ask you to confirm</strong><span>Repository contents · Read and write</span><span>Events · No Webhook subscriptions</span><span>Installation · You choose the repositories on GitHub</span></div><div class="form-error" hidden></div><button class="button primary manifest-submit" type="submit">${icon('git')}Continue on GitHub</button><button class="text-action" id="manualGitHub" type="button">Advanced manual configuration</button></form>`,()=>{$('#githubManifestForm').onsubmit=startGitHubManifest;$('#manualGitHub').onclick=()=>manualProviderSettingsForm('github',current)})}
async function manualProviderSettingsForm(provider,current={}){const system=await api('/api/system/settings');if(!system.publicUrl){openDrawer('System address required',`<section class="connection-problem"><span class="entity-mark">${icon('settings')}</span><h3>Set the ProjectBoard address once</h3><p>The provider uses it only to return your browser after confirmation. Localhost works.</p><button class="button primary" id="openSystemSettings" type="button">Open system settings</button></section>`,()=>{$('#openSystemSettings').onclick=()=>navigate('globalSettings')});return}const github=provider==='github';const secretHint=value=>value?'Configured · leave blank to keep the saved value':'Required for first setup';const fields=github?field('GitHub App ID','appId','text',current.appId||'','required')+field('GitHub App slug','appSlug','text',current.appSlug||'','required')+area('GitHub App private key (PEM)','privateKey','',current.privateKeyConfigured?'placeholder="Configured — leave blank to keep"':'required placeholder="-----BEGIN PRIVATE KEY-----"'):field('GitLab OAuth application ID','clientId','text',current.clientId||'','required')+field('GitLab base URL','baseUrl','url',current.baseUrl||'https://gitlab.com','required')+field(`OAuth application secret · ${secretHint(current.clientSecretConfigured)}`,'clientSecret','password','',current.clientSecretConfigured?'autocomplete="new-password"':'required autocomplete="new-password"');openDrawer(`Advanced ${github?'GitHub App':'GitLab OAuth'} configuration`,`<p class="drawer-note">Use this fallback only when the automatic provider flow is unavailable. No Webhook settings are required.</p><form class="form provider-settings-form" id="providerSettingsForm">${fields}<div class="provider-callbacks"><strong>Provider callback</strong><code>${escapeHTML(system.publicUrl+`/api/git/connections/${provider}/callback`)}</code></div><div class="form-error" hidden></div><button class="button primary" type="submit">Save and enable ${github?'GitHub':'GitLab'}</button></form>`,()=>{$('#providerSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api(`/api/git/provider-settings/${provider}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast(`${github?'GitHub':'GitLab'} configuration saved`);await grantForm()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}})}
async function startGitHubManifest(event){event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),popup=window.open('about:blank','projectboard-github-app','popup,width=760,height=780');if(!popup){error.textContent='Pop-up blocked. Allow pop-ups for ProjectBoard and try again.';error.hidden=false;return}button.disabled=true;error.hidden=true;try{const input=Object.fromEntries(new FormData(form));const flow=await api('/api/git/provider-settings/github/manifest/start',{method:'POST',body:JSON.stringify(input)});const post=popup.document.createElement('form');post.method='post';post.action=flow.registrationUrl;const manifest=popup.document.createElement('input');manifest.type='hidden';manifest.name='manifest';manifest.value=flow.manifest;post.append(manifest);popup.document.body.append(post);post.submit();openDrawer('Creating the GitHub App',`<div class="connection-progress"><span class="progress-mark">${icon('git')}</span><h3>Confirm once on GitHub</h3><p>Review the generated App name and permissions, then choose <strong>Create GitHub App</strong>. ProjectBoard will securely collect the generated settings.</p><button class="button" id="leaveManifestSetup" type="button">Cancel setup</button></div>`,()=>{$('#leaveManifestSetup').onclick=async()=>{clearInterval(state.gitPoll);popup.close();try{await api(`/api/git/provider-settings/github/manifest-flows/${flow.id}/cancel`,{method:'POST',body:'{}'})}catch{}grantForm()}});pollGitHubManifest(flow.id,popup)}catch(x){popup.close();error.textContent=x.message;error.hidden=false;button.disabled=false}}
function pollGitHubManifest(id,popup){clearInterval(state.gitPoll);let checking=false;const check=async()=>{if(checking)return;checking=true;try{const flow=await api(`/api/git/provider-settings/github/manifest-flows/${id}`);if(flow.status==='completed'){clearInterval(state.gitPoll);popup?.close();toast('GitHub App configured automatically');await grantForm()}else if(flow.status==='failed'){clearInterval(state.gitPoll);popup?.close();renderGitConnectionProblem({provider:'github',status:'failed',errorCode:flow.errorCode,errorMessage:flow.errorMessage})}}catch(error){clearInterval(state.gitPoll);popup?.close();renderGitConnectionProblem({provider:'github',status:'failed',errorCode:'SETUP_STATUS_FAILED',errorMessage:error.message})}finally{checking=false}};check();state.gitPoll=setInterval(check,1200)}
async function startGitConnection(provider){const popup=window.open('about:blank','projectboard-git-connect','popup,width=720,height=760');openDrawer(`Connecting ${provider==='github'?'GitHub':'GitLab'}`,`<div class="connection-progress"><span class="progress-mark">${icon('git')}</span><h3>Waiting for provider authorization</h3><p>Choose repositories on the official provider page. ProjectBoard will continue here after the callback is verified.</p><button class="button" id="cancelGitConnection" type="button">Cancel connection</button></div>`);try{const flow=await api(`/api/git/connections/${provider}/start`,{method:'POST',body:JSON.stringify({projectId:state.project.id})});if(popup)popup.location=flow.authorizationUrl;else toast('Pop-up blocked. Allow pop-ups and try again.');$('#cancelGitConnection').onclick=async()=>{await api(`/api/git/connection-flows/${flow.id}/cancel`,{method:'POST',body:'{}'});popup?.close();renderGitConnectionProblem({provider,status:'canceled',errorCode:'AUTHORIZATION_CANCELED',errorMessage:'The connection was canceled before a project grant was created.'})};pollGitConnection(flow.id,popup)}catch(error){popup?.close();renderGitConnectionProblem({provider,status:'failed',errorCode:'START_FAILED',errorMessage:error.message})}}
function pollGitConnection(id,popup){clearInterval(state.gitPoll);let checking=false;const check=async()=>{if(checking)return;checking=true;try{const flow=await api(`/api/git/connection-flows/${id}`);if(flow.status==='ready'){clearInterval(state.gitPoll);popup?.close();renderGitConnectionReview(flow)}else if(['failed','canceled','expired'].includes(flow.status)){clearInterval(state.gitPoll);popup?.close();renderGitConnectionProblem(flow)}}catch(error){clearInterval(state.gitPoll);renderGitConnectionProblem({status:'failed',errorCode:'STATUS_FAILED',errorMessage:error.message})}finally{checking=false}};check();state.gitPoll=setInterval(check,1200)}
function renderGitConnectionReview(flow){const selected=flow.matchedRepositoryId||flow.repositories[0]?.id||'';const options=flow.repositories.map(repo=>`<option value="${repo.id}" ${repo.id===selected?'selected':''}>${escapeHTML(repo.name)}${repo.canWrite?'':' · read only'}</option>`).join('');const attention=flow.errorCode==='NO_MATCHING_REPOSITORY'?'<p class="connection-warning">No repository matched the project URL. Choose the intended repository explicitly before continuing.</p>':'';openDrawer('Review project Git access',`<section class="connection-review"><div class="review-status">${badge('provider connected','signal')}${badge('on-demand commit sync','signal')}</div><h3>Confirm the project binding</h3><p>Nothing is bound until you confirm the repository and access below.</p>${attention}<form class="form" id="gitConnectionForm"><label class="field"><span>Repository</span><select name="repositoryId" required>${options}</select></label><label class="field"><span>Access level</span><select name="accessLevel"><option value="write">Read and write</option><option value="read">Read only</option></select></label><div class="permission-summary"><strong>Effective boundary</strong><span>One project · one repository · selected read/write scope</span><span>Recent commits are queried only after a person or active Runner requests a sync.</span></div><div class="form-error" hidden></div><button class="button primary" type="submit">Create project repository grant</button></form></section>`,()=>wireForm('#gitConnectionForm',d=>api(`/api/git/connection-flows/${flow.id}/complete`,{method:'POST',body:JSON.stringify(d)})))}
function renderGitConnectionProblem(flow){const messages={AUTHORIZATION_CANCELED:'Authorization was canceled. No project grant was created.',CALLBACK_EXPIRED:'The callback expired. Start a new connection and complete it within 15 minutes.',NO_ACCESSIBLE_REPOSITORIES:'The provider returned no accessible repositories. Update the installation or account permissions, then retry.',INSUFFICIENT_PROVIDER_PERMISSION:'The provider did not grant the required permission. Update the provider authorization and retry.'};openDrawer('Git setup needs attention',`<section class="connection-problem"><span class="entity-mark">${icon('x')}</span><h3>${escapeHTML(flow.errorCode||'CONNECTION_FAILED')}</h3><p>${escapeHTML(messages[flow.errorCode]||flow.errorMessage||'The provider connection could not be completed.')}</p><div class="drawer-actions"><button class="button primary" id="retryGitConnection" type="button">Try again</button><button class="button" id="closeGitProblem" type="button">Close</button></div></section>`,()=>{$('#retryGitConnection').onclick=grantForm;$('#closeGitProblem').onclick=closeDrawer})}
async function reuseAuthorization(id,authorization){const repositories=await api(`/api/provider-authorizations/${id}/repositories`);if(!repositories.length){renderGitConnectionProblem({errorCode:'NO_ACCESSIBLE_REPOSITORIES'});return}const matched=repositories.find(repo=>normalizedRepositoryURL(repo.cloneUrl)===normalizedRepositoryURL(state.project.repositoryUrl));const options=repositories.map(repo=>`<option value="${repo.id}" ${repo===matched?'selected':''}>${escapeHTML(repo.name)}${repo.canWrite?'':' · read only'}</option>`).join('');openDrawer('Reuse verified connection',formShell(`<input type="hidden" name="authorizationId" value="${id}"><label class="field"><span>Connection</span><input value="${escapeHTML(authorization.name)}" disabled></label><label class="field"><span>Repository</span><select name="repositoryId" id="reusedRepository" required>${options}</select></label><label class="field"><span>Access level</span><select name="accessLevel"><option value="write">Read and write</option><option value="read">Read only</option></select></label>`,'This creates a separate revocable grant for the current project. Confirm the exact repository and access level.'),()=>wireForm('#drawerForm',d=>{const repo=repositories.find(item=>item.id===d.repositoryId);return api(`/api/projects/${state.project.id}/repository-grant`,{method:'POST',body:JSON.stringify({...d,repositoryName:repo.name,cloneUrl:repo.cloneUrl,defaultBranch:repo.defaultBranch})})}))}
function normalizedRepositoryURL(value=''){return value.toLowerCase().replace(/^git@/,'').replace(':','/').replace(/^https?:\/\//,'').replace(/^ssh:\/\//,'').replace(/\.git$/,'').replace(/\/$/,'')}
function providerAuthorizationForm(){const fields=field('Connection name','name','text','GitLab access token','required')+field('GitLab base URL','baseUrl','url','https://gitlab.com','required')+area('Personal or project access token','secret','','required')+field('Repository ID','repositoryId','text','','required')+field('Repository name','repositoryName','text','','required')+field('Clone URL','cloneUrl','url',state.project.repositoryUrl,'required')+field('Default branch','defaultBranch','text',state.project.defaultTargetBranch,'required')+`<label class="field"><span>Access level</span><select name="accessLevel"><option value="write">Read and write</option><option value="read">Read only</option></select></label><input type="hidden" name="provider" value="gitlab">`;openDrawer('Advanced GitLab token setup',formShell(fields,'Use this only when you cannot create a GitLab OAuth application. The token is encrypted server-side; recent commits sync only on request.'),()=>wireForm('#drawerForm',async d=>{const grant={repositoryId:d.repositoryId,repositoryName:d.repositoryName,cloneUrl:d.cloneUrl,defaultBranch:d.defaultBranch,accessLevel:d.accessLevel};delete d.repositoryId;delete d.repositoryName;delete d.cloneUrl;delete d.defaultBranch;delete d.accessLevel;const authorization=await api('/api/provider-authorizations',{method:'POST',body:JSON.stringify(d)});return api(`/api/projects/${state.project.id}/repository-grant`,{method:'POST',body:JSON.stringify({...grant,authorizationId:authorization.id})})}))}
async function renderUsers(){const data=await api('/api/users');const actions=`<button class="button primary" id="newUser">${icon('plus')}${t('createUser')}</button>`;const rows=data.map(x=>`<button class="table-row action user-row" data-user="${x.id}" aria-label="Open settings for ${escapeHTML(x.displayName)}"><span class="user-identity"><span class="user-avatar">${escapeHTML(x.displayName.trim().slice(0,1).toUpperCase()||'?')}</span><span><strong>${escapeHTML(x.displayName)}</strong><small>@${escapeHTML(x.username)}</small></span></span><span>${escapeHTML(x.systemRole)}</span><span>${x.membershipCount} projects</span><span class="user-status">${badge(x.status,x.status==='disabled'?'danger':'')}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('users'),'Organization accounts; select a user to manage profile, access, and security.',actions)+`<div class="content"><div class="table">${rows}</div></div>`;$('#newUser').onclick=userForm;document.querySelectorAll('[data-user]').forEach(row=>row.onclick=()=>userSettings(row.dataset.user))}
async function userSettings(id){openDrawer('User settings','<div class="drawer-loading">Loading account…</div>');try{const user=await api(`/api/users/${id}`);renderUserSettings(user)}catch(error){const loading=$('#drawer .drawer-loading');if(loading)loading.outerHTML=`<div class="form-error">${escapeHTML(error.message)}</div>`}}
function renderUserSettings(user){const drawer=$('#drawer');if(!drawer)return;const isSelf=user.id===state.me.id;const memberships=(user.memberships||[]).map(m=>`<div><dt>${escapeHTML(m.name)}</dt><dd>${badge(m.role,m.role==='developer'?'signal':'')}</dd></div>`).join('')||'<p class="empty-note">This user has not joined any projects.</p>';drawer.innerHTML=`<header class="drawer-head"><div><span class="eyebrow">USER ACCOUNT / @${escapeHTML(user.username)}</span><h2>${escapeHTML(user.displayName)}</h2></div><button class="icon-button" id="closeDrawer" aria-label="${t('close')}">${icon('x')}</button></header><section class="user-summary"><div class="user-avatar large">${escapeHTML(user.displayName.trim().slice(0,1).toUpperCase()||'?')}</div><div><div class="user-summary-badges">${badge(user.status,user.status==='disabled'?'danger':'')}${isSelf?badge('current account','signal'):''}</div><p>${user.status==='disabled'?'Sign-in is disabled. Memberships and historical attribution are preserved.':'This account can sign in and use its assigned project memberships.'}</p></div></section><form class="form user-settings-form" id="userSettingsForm">${field('Display name','displayName','text',user.displayName,'required')}<label class="field"><span>Username</span><input value="@${escapeHTML(user.username)}" disabled></label><label class="field"><span>System role</span><select name="systemRole"><option value="user" ${user.systemRole==='user'?'selected':''}>User</option><option value="administrator" ${user.systemRole==='administrator'?'selected':''}>Administrator</option></select></label><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form><section class="drawer-section"><span class="eyebrow">PROJECT ACCESS / ${(user.memberships||[]).length}</span><div class="kv user-memberships">${memberships}</div></section><section class="drawer-section security-section"><span class="eyebrow">ACCOUNT SECURITY</span><p>Password reset revokes active sessions. Disabling an account preserves its project relationships and history.</p><div class="drawer-actions"><button class="button" id="resetUserPassword" type="button">${icon('shield')}Reset password</button>${user.status==='disabled'?'<button class="button primary" id="toggleUserStatus" type="button">Enable user</button>':`<button class="button danger" id="toggleUserStatus" type="button" ${isSelf?'disabled title="You cannot disable your own account"':''}>Disable user</button>`}</div>${isSelf?'<p class="inline-note">You cannot disable the account you are currently using.</p>':''}</section>`;$('#closeDrawer').onclick=closeDrawer;$('#userSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api(`/api/users/${user.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast('User settings saved');await renderUsers();await userSettings(user.id)}catch(x){error.textContent=x.message;error.hidden=false}finally{button.disabled=false}};$('#resetUserPassword').onclick=()=>resetUserPassword(user);const toggle=$('#toggleUserStatus');if(toggle)toggle.onclick=()=>user.status==='disabled'?enableUser(user):disableUser(user)}
async function resetUserPassword(user){const button=$('#resetUserPassword');button.disabled=true;try{const result=await api(`/api/users/${user.id}/reset-password`,{method:'POST',body:'{}'});openDrawer('Temporary password',`<p class="drawer-note">This password is shown once. Send it to ${escapeHTML(user.displayName)} through a secure channel.</p><div class="secret-reveal"><code id="temporaryPassword">${escapeHTML(result.temporaryPassword)}</code><button class="button" id="copyTemporaryPassword" type="button">Copy</button></div>`,()=>{$('#copyTemporaryPassword').onclick=async()=>{await navigator.clipboard.writeText(result.temporaryPassword);toast('Temporary password copied')}})}catch(error){toast(error.message);button.disabled=false}}
function disableUser(user){openDrawer('Disable user',formShell(area('Reason','reason','','required'),'The user will be signed out immediately. Project memberships and historical attribution remain intact.'),()=>wireForm('#drawerForm',d=>api(`/api/users/${user.id}/disable`,{method:'POST',body:JSON.stringify(d)})))}
async function enableUser(user){const button=$('#toggleUserStatus');button.disabled=true;try{await api(`/api/users/${user.id}/enable`,{method:'POST',body:'{}'});toast('User enabled');await renderUsers();await userSettings(user.id)}catch(error){toast(error.message);button.disabled=false}}
function userForm(){const fields=field('Display name','displayName','text','','required')+field('Username','username','text','','required pattern="[a-z0-9._-]{2,64}"')+`<label class="field"><span>System role</span><select name="systemRole"><option value="user">User</option><option value="administrator">Administrator</option></select></label>`;openDrawer(t('createUser'),formShell(fields,'ProjectBoard generates a password and displays it once.'),()=>wireForm('#drawerForm',async d=>{const result=await api('/api/users',{method:'POST',body:JSON.stringify(d)});toast(`Temporary password: ${result.temporaryPassword}`)}))}
async function renderProjects(){const actions=`<button class="button primary" id="newProject">${icon('plus')}${t('createProject')}</button>`;const rows=state.projects.map(p=>`<button class="table-row action management-row" data-managed-project="${p.id}"><span><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.key)}</small></span><span>${badge(p.archivedAt?'archived':'active',p.archivedAt?'':'signal')}</span><span>${escapeHTML(p.repositoryUrl)}</span><span class="row-end">${escapeHTML(p.defaultTargetBranch)}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('projects'),'Organization workspaces and repository routes. Select a project to inspect or edit it.',actions)+`<div class="content"><div class="table">${rows||emptyState(t('noProjects'),t('noProjectsNote'))}</div></div>`;$('#newProject').onclick=projectForm;document.querySelectorAll('[data-managed-project]').forEach(row=>row.onclick=()=>projectSettings(state.projects.find(p=>p.id===row.dataset.managedProject)))}
function projectSettings(project){const isCurrent=project.id===state.project?.id;openDrawer('Project settings',`<section class="entity-summary"><span class="project-mark large">${escapeHTML(project.key.slice(0,2).toUpperCase())}</span><div><span class="eyebrow">PROJECT / ${escapeHTML(project.key)}</span><h3>${escapeHTML(project.name)}</h3><div>${badge(project.archivedAt?'archived':'active',project.archivedAt?'':'signal')} ${isCurrent?badge('current','signal'):''}</div></div></section><section class="drawer-section"><div class="kv"><div><dt>Repository</dt><dd>${escapeHTML(project.repositoryUrl)}</dd></div><div><dt>Default target</dt><dd>${escapeHTML(project.defaultTargetBranch)}</dd></div><div><dt>Allowed targets</dt><dd>${escapeHTML((project.allowedTargetBranches||[]).join(', ')||'—')}</dd></div><div><dt>Config version</dt><dd>${project.configVersion}</dd></div></div></section><div class="drawer-actions"><button class="button primary" id="openProject" type="button">${isCurrent?'Open task queue':'Switch to project'}</button><button class="button" id="editManagedProject" type="button">${icon('settings')}Edit settings</button></div>`,()=>{$('#openProject').onclick=()=>{state.project=project;localStorage.pbProject=project.id;state.page='queue';closeDrawer();renderShell()};$('#editManagedProject').onclick=()=>editProjectForm(project)})}
async function renderActivity(){const data=state.project?await api(`/api/activity?projectId=${state.project.id}`):[];const rows=data.map((e,index)=>`<button class="table-row action management-row" data-event="${index}"><span><strong>${escapeHTML(e.event_type)}</strong><small>${escapeHTML(e.created_at)}</small></span><span>${escapeHTML(e.actor_type)}</span><span>${escapeHTML(e.object_type)}</span><span class="row-end">${escapeHTML(e.object_id)}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('activity'),'Append-only operational evidence. Select an event to inspect its recorded details.')+`<div class="content"><div class="table">${rows||'<p>No activity recorded.</p>'}</div></div>`;document.querySelectorAll('[data-event]').forEach(row=>row.onclick=()=>activityDetails(data[Number(row.dataset.event)]))}
function activityDetails(event){let payload={};try{payload=JSON.parse(event.payload_json||'{}')}catch{payload={raw:event.payload_json}}const entries=Object.entries(payload).map(([key,value])=>`<div><dt>${escapeHTML(key)}</dt><dd>${escapeHTML(typeof value==='object'?JSON.stringify(value):value)}</dd></div>`).join()||'<p class="empty-note">No additional payload was recorded.</p>';openDrawer('Activity details',`<section class="entity-summary"><span class="entity-mark">${icon('activity')}</span><div><span class="eyebrow">AUDIT EVENT</span><h3>${escapeHTML(event.event_type)}</h3><div>${badge(event.source||'web')} ${badge(event.actor_type)}</div></div></section><section class="drawer-section"><div class="kv"><div><dt>Occurred</dt><dd>${escapeHTML(event.created_at)}</dd></div><div><dt>Actor ID</dt><dd>${escapeHTML(event.actor_id||'—')}</dd></div><div><dt>Object</dt><dd>${escapeHTML(`${event.object_type} / ${event.object_id}`)}</dd></div><div><dt>Event ID</dt><dd>${escapeHTML(event.id)}</dd></div></div></section><section class="drawer-section"><span class="eyebrow">RECORDED PAYLOAD</span><div class="kv payload-kv">${entries}</div></section>`)}
function passwordForm(){openDrawer('Change password',formShell(field('Current password','currentPassword','password','','required')+field('New password','newPassword','password','','required minlength="12"')),()=>wireForm('#drawerForm',d=>api('/api/me/change-password',{method:'POST',body:JSON.stringify(d)})))}
renderSystemSettings=async function(){
  const settings=await api('/api/system/settings');
  const value=settings.publicUrl||location.origin;
  $('#workspace').innerHTML=header(t('globalSettings'),'')+`<div class="content simple-settings-page">
    <section class="settings-sheet">
      <header class="settings-sheet-head"><h2>服务地址</h2><span class="setting-state">${settings.publicUrl?'已配置':'未保存'}</span></header>
      <form class="simple-setting-form" id="systemSettingsForm">${field('ProjectBoard URL','publicUrl','url',value,'required')}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>
    </section>
  </div>`;
  $('#systemSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api('/api/system/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast('系统设置已保存');renderSystemSettings()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}};
};

renderSettings=async function(){
  if(!state.project)return renderQueue();
  let grant=null;try{grant=await api(`/api/projects/${state.project.id}/repository-grant`)}catch{}
  const actions=`<button class="button" id="editProject">编辑项目</button>${grant?`<button class="button" id="syncCommits">${icon('activity')}同步最近提交</button>`:''}<button class="button primary" id="gitGrant">${icon('git')}${grant?'更改 Git 授权':'自动配置 Git'}</button>`;
  const grantDetails=grant?`<dl class="simple-setting-rows"><div><dt>状态</dt><dd><span class="setting-state blue">已连接</span></dd></div><div><dt>仓库</dt><dd>${escapeHTML(grant.repositoryName)}</dd></div><div><dt>提供商</dt><dd>${escapeHTML(grant.provider)}</dd></div><div><dt>访问范围</dt><dd>${escapeHTML(grant.accessLevel)}</dd></div><div><dt>同步方式</dt><dd>按需</dd></div></dl>`:`<div class="simple-empty-setting"><span class="setting-state">未连接</span><strong>尚未配置 Git 仓库</strong></div>`;
  $('#workspace').innerHTML=header(t('settings'),escapeHTML(state.project.name),actions)+`<div class="content simple-settings-page project-simple-settings">
    <section class="settings-sheet">
      <header class="settings-sheet-head"><h2>Git 仓库</h2></header>${grantDetails}
    </section>
    <section class="settings-sheet">
      <header class="settings-sheet-head"><h2>仓库与分支</h2><span class="setting-state">版本 ${state.project.configVersion}</span></header>
      <dl class="simple-setting-rows"><div><dt>Repository URL</dt><dd>${escapeHTML(state.project.repositoryUrl)}</dd></div><div><dt>默认分支</dt><dd>${escapeHTML(state.project.defaultTargetBranch)}</dd></div><div><dt>允许分支</dt><dd>${escapeHTML((state.project.allowedTargetBranches||[]).join(', ')||'未设置')}</dd></div></dl>
    </section>
  </div>`;
  $('#editProject').onclick=()=>editProjectForm(state.project);$('#gitGrant').onclick=grantForm;const sync=$('#syncCommits');if(sync)sync.onclick=async()=>{sync.disabled=true;try{const result=await api(`/api/projects/${state.project.id}/sync-commits`,{method:'POST',body:'{}'});toast(`已查询 ${result.fetched} 条提交，新增关联 ${result.inserted} 条`)}catch(error){toast(error.message)}finally{sync.disabled=false}};
};

zh.runnerDownloads='Runner 下载';
en.runnerDownloads='Runner downloads';
nav2.splice(2,0,['runnerDownloads','download']);

async function renderRunnerDownloads(){
  const result=await api('/api/runner/downloads');
  const downloads=result.downloads||[];
  const rows=downloads.map(item=>`<a class="runner-download-row" href="${escapeHTML(item.url)}" download="${escapeHTML(item.name)}"><span class="runner-download-icon">${icon('download')}</span><span><strong>${escapeHTML(item.platform)}</strong><small>${escapeHTML(item.arch)} · ${formatDownloadSize(item.size)}</small></span><span class="button primary">下载</span></a>`).join('');
  $('#workspace').innerHTML=header(t('runnerDownloads'),'')+`<div class="content simple-settings-page"><section class="settings-sheet"><header class="settings-sheet-head"><h2>可用版本</h2><span class="setting-state">${downloads.length}</span></header><div class="runner-download-list">${rows||'<div class="simple-empty-setting"><strong>暂无可下载的 Runner</strong></div>'}</div></section></div>`;
}

function formatDownloadSize(bytes){
  if(bytes<1024*1024)return `${Math.max(1,Math.round(bytes/1024))} KB`;
  return `${(bytes/1024/1024).toFixed(1)} MB`;
}

const renderPageWithoutRunnerDownloads=renderPage;
renderPage=async function(){
  if(state.page==='runnerDownloads')return renderRunnerDownloads();
  return renderPageWithoutRunnerDownloads();
};

async function renderAccount(){
  const actions=`<button class="button" id="signOut">${icon('log-out')}${t('logout')}</button>`;
  $('#workspace').innerHTML=header(t('account'),'',actions)+`<div class="content settings-grid"><section class="settings-section"><h2>${escapeHTML(state.me.displayName)}</h2><div class="kv"><div><dt>Username</dt><dd>${escapeHTML(state.me.username)}</dd></div><div><dt>Role</dt><dd>${escapeHTML(state.me.systemRole)}</dd></div><div><dt>Status</dt><dd>${escapeHTML(state.me.status)}</dd></div></div></section><section class="settings-section"><h2>Security</h2><button class="button" id="changePassword">Change password</button></section></div>`;
  $('#signOut').onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});state.me=null;renderLogin()};$('#changePassword').onclick=passwordForm;
}

boot();
